                foreach (var member in Enum.GetValues(type))
                {
                    var written = JsonSerializer.SerializeToElement(member, type, options);
                    values.Add(written.ValueKind == JsonValueKind.String ? written.GetString()! : written.GetRawText());
                }
            }
            catch (Exception ex) when (ex is JsonException or NotSupportedException or InvalidOperationException)
            {
                return null;
            }
            return values.Count == 0 ? null : string.Join(", ", values);
        }

        /// <summary>
        /// The options for each serializer options instance and property, built once because creating
        /// <see cref="JsonSerializerOptions"/> rebuilds the serializer's metadata cache.
        /// </summary>
        private static readonly System.Runtime.CompilerServices.ConditionalWeakTable<JsonSerializerOptions, System.Collections.Concurrent.ConcurrentDictionary<PropertyInfo, JsonSerializerOptions>> _propertyReadOptions = new();

        /// <summary>
        /// Returns <paramref name="options"/> with the <c>[JsonConverter]</c> and
        /// <c>[JsonNumberHandling]</c> declared on <paramref name="property"/> applied, so a value
        /// is read the way deserializing the whole model reads it.
        /// </summary>
        private static JsonSerializerOptions PropertyReadOptions(PropertyInfo property, JsonSerializerOptions? options)
        {
            options ??= JsonSerializerOptions.Default;
            return _propertyReadOptions.GetOrCreateValue(options).GetOrAdd(property, static (member, baseOptions) =>
            {
                var converterAttribute = member.GetCustomAttribute<JsonConverterAttribute>();
                var converter = converterAttribute is null
                    ? null
                    : converterAttribute.CreateConverter(member.PropertyType)
                        ?? (converterAttribute.ConverterType is { } converterType ? (JsonConverter?)Activator.CreateInstance(converterType) : null);
                var numberHandling = member.GetCustomAttribute<JsonNumberHandlingAttribute>()?.Handling;
                if (converter is null && numberHandling is null) return baseOptions;
                var propertyOptions = new JsonSerializerOptions(baseOptions);
                if (converter is not null) propertyOptions.Converters.Insert(0, converter);
                if (numberHandling is { } handling) propertyOptions.NumberHandling = handling;
                return propertyOptions;
            }, options);
        }

        /// <summary>
        /// Serializes <paramref name="value"/> and stores it as a patch entry for the
        /// property named <paramref name="name"/>. Pass <see langword="null"/> to mark
        /// the field for clearing (RFC 7396 semantics).
        /// Returns <see langword="false"/> when serialization fails.
        /// </summary>
        public bool TrySetPropertyValue(string name, object? value, JsonSerializerOptions? options = null)
        {
            try
            {
                using var doc = JsonDocument.Parse(JsonSerializer.Serialize(value, options));
                Properties[name] = doc.RootElement.Clone();
                return true;
            }
            catch
            {
                return false;
            }
        }

        /// <summary>
        /// Constructs a <see cref="MergePatch{T}"/> from a JSON string, treating every
        /// property present in the JSON as explicitly defined in the patch.
        /// </summary>
        /// <remarks>
        /// Properties are keyed by their JSON wire names. If <typeparamref name="T"/> uses
        /// <c>[JsonPropertyName]</c> attributes or a custom <see cref="JsonSerializerOptions"/>
        /// naming policy, the keys in <see cref="Properties"/> will reflect those wire names
        /// and may not match C# property names used by <see cref="Patch(T, JsonSerializerOptions?)"/>.
        /// </remarks>
        public static MergePatch<T> FromJson(string json, JsonSerializerOptions? options = null) =>
            JsonSerializer.Deserialize<MergePatch<T>>(json, options) ?? new MergePatch<T>();

        /// <summary>
        /// Constructs a <see cref="MergePatch{T}"/> from an existing <typeparamref name="T"/>
        /// instance by serializing it to JSON. Every property that is included in the serialized
        /// output is treated as explicitly defined in the patch.
        /// </summary>
        /// <remarks>
        /// Serialization honours <paramref name="options"/> (including
        /// <c>DefaultIgnoreCondition</c>). Pass <see langword="null"/> options to include all
        /// properties, even those with <see langword="null"/> values.
        /// </remarks>
        public static MergePatch<T> From(T entity, JsonSerializerOptions? options = null) =>
            FromJson(JsonSerializer.Serialize(entity, options), options);

        /// <summary>
        /// Applies defined properties recursively to <paramref name="original"/> in place.
        /// Use <see cref="TryPatch"/> when rejected-path diagnostics are needed.
        /// </summary>
        public void Patch(T original, JsonSerializerOptions? options = null)
        {
            TryPatch(original, out _, options);
        }

        /// <summary>
        /// Applies each defined patch property recursively to <paramref name="original"/>.
        /// Invalid, unknown, and read-only properties are reported and skipped; valid
        /// sibling properties are still applied. The root instance is never replaced.
        /// Nested models are merged in place unless a discriminator selects a different
        /// subtype, in which case a replacement retains shared serialized properties.
        /// A property marked <c>[JsonObjectCreationHandling(JsonObjectCreationHandling.Replace)]</c>,
        /// as <c>@patchStrategy("replace")</c> emits, is replaced by the supplied object instead.
        /// Members are resolved from the runtime type of <paramref name="original"/>, so
        /// the properties of a derived type can be patched through its base type.
        /// </summary>
        /// <param name="original">The entity to mutate.</param>
        /// <param name="rejectedPaths">JSON property paths that could not be applied.</param>
        /// <param name="options">Serializer options used for the entity and patch values; defaults to <see cref="ReadOptions"/>.</param>
        /// <returns><see langword="true"/> when every supplied property was applied.</returns>
        public bool TryPatch(T original, out IReadOnlyList<string> rejectedPaths, JsonSerializerOptions? options = null)
        {
            var rejected = new List<string>();
            rejectedPaths = rejected;
            if (original is null)
            {
                rejected.Add("$");
                return false;
            }

            PatchObject(original, original.GetType(), Properties, rejected, string.Empty, options ?? ReadOptions);
            return rejected.Count == 0;
        }

        private readonly record struct PatchEntry(PropertyInfo Property, string Name, JsonElement Value);

        /// <summary>
        /// Applies <paramref name="values"/> to <paramref name="target"/> in place. An object value
        /// for a property that already holds a model instance of the selected subtype is merged into that instance. Every
        /// other value is applied in one serialize/merge/deserialize round trip; only when that
        /// fails is each value retried alone, so one bad value cannot block its valid siblings
        /// and the failing path can be reported.
        /// </summary>
        private static void PatchObject(object target, Type type, IEnumerable<KeyValuePair<string, JsonElement>> values, List<string> rejected, string prefix, JsonSerializerOptions? options)
        {
            var patchObject = new JsonObject();
            foreach (var (name, value) in values) patchObject[name] = JsonNode.Parse(value.GetRawText(), documentOptions: new JsonDocumentOptions { MaxDepth = options?.MaxDepth ?? 0 });
            if (!TryResolvePatchType(type, type, null, patchObject, rejected, prefix, out _, out var discriminatorName)) return;
            var entries = new List<PatchEntry>();
            foreach (var (name, element) in values)
            {
                if (string.Equals(name, discriminatorName, StringComparison.OrdinalIgnoreCase)) continue;
                var member = FindMember(type, name);
                if (member is null)
                {
                    rejected.Add(JoinPath(prefix, name));
                    continue;
                }
                var property = member.Value.Property;
                // A read-only property is rejected before any merge, so a nested object
                // behind a getter-only property is never mutated.
                if (!property.CanWrite)
                {
                    rejected.Add(JoinPath(prefix, name));
                    continue;
                }
                if (element.ValueKind == JsonValueKind.Object
                    && property.CanRead
                    && IsModelType(property.PropertyType)
                    && !ReplacesOnPatch(property)
                    && property.GetValue(target) is { } nested)
                {
                    var nestedPatch = (JsonObject)JsonNode.Parse(element.GetRawText(), documentOptions: new JsonDocumentOptions { MaxDepth = options?.MaxDepth ?? 0 })!;
                    if (!TryResolvePatchType(property.PropertyType, nested.GetType(), null, nestedPatch, rejected, JoinPath(prefix, member.Value.WireName), out var nestedType, out _, allowReplacement: true)) continue;
                    if (nestedType != nested.GetType())
                    {
                        entries.Add(new PatchEntry(property, name, element));
                        continue;
                    }
                    var nestedValues = new List<KeyValuePair<string, JsonElement>>();
                    foreach (var nestedProperty in element.EnumerateObject())
                    {
                        nestedValues.Add(new(nestedProperty.Name, nestedProperty.Value));
                    }
                    PatchObject(nested, nested.GetType(), nestedValues, rejected, JoinPath(prefix, member.Value.WireName), options);
                    continue;
                }
                entries.Add(new PatchEntry(property, name, element));
            }
            if (entries.Count == 0) return;

            var batchRejected = new List<string>();
            if (TryApply(target, type, entries, batchRejected, prefix, options, out _))
            {
                rejected.AddRange(batchRejected);
                return;
            }

            foreach (var entry in entries)
            {
                if (!TryApply(target, type, new[] { entry }, rejected, prefix, options, out var failedPath))
                {
                    rejected.Add(failedPath ?? JoinPath(prefix, entry.Name));
                }
            }
        }

        /// <summary>
        /// Merges <paramref name="entries"/> into a JSON copy of <paramref name="target"/>,
        /// deserializes it as <paramref name="type"/>, and copies the patched properties back.
        /// Nested paths that cannot be merged are added to <paramref name="rejected"/>. On failure
        /// nothing is copied and <paramref name="failedPath"/> holds the JSON path of the bad value
        /// when the serializer reported one.
        /// </summary>
        private static bool TryApply(object target, Type type, IReadOnlyList<PatchEntry> entries, List<string> rejected, string prefix, JsonSerializerOptions? options, out string? failedPath)
        {
            failedPath = null;
            try
            {
                if (JsonSerializer.SerializeToNode(target, type, options) is not JsonObject node) return false;

                var patch = new JsonObject();
                foreach (var entry in entries)
                {
                    patch[entry.Name] = JsonNode.Parse(entry.Value.GetRawText(), documentOptions: new JsonDocumentOptions { MaxDepth = options?.MaxDepth ?? 0 });
                }
                var rejectedObjects = new List<string[]>();
                MergeObject(node, patch, type, rejected, prefix, rejectedObjects, Array.Empty<string>());

                var updated = node.Deserialize(type, options);
                if (updated is null) return false;
                RestoreRejectedObjects(target, updated, rejectedObjects);
                foreach (var entry in entries)
                {
                    entry.Property.SetValue(target, entry.Property.GetValue(updated));
                }
                return true;
            }
            catch (JsonException ex)
            {
                var path = ex.Path;
                var relativePath = path is { Length: > 1 } && path.StartsWith("$.", StringComparison.Ordinal)
                    ? path[2..]
                    : path is { Length: > 1 } && path[0] == '$'
                        ? path[1..]
                        : null;
                failedPath = relativePath is null ? null : JoinPath(prefix, relativePath);
                return false;
            }
            catch
            {
                return false;
            }
        }

        private static string JoinPath(string prefix, string name) => prefix.Length == 0 ? name : $"{prefix}.{name}";

        private static bool TryResolvePatchType(Type declaredType, Type? runtimeType, JsonObject? existing, JsonObject patch, List<string> rejected, string prefix, out Type resolvedType, out string? discriminatorName, bool allowReplacement = false)
        {
            resolvedType = runtimeType ?? declaredType;
            discriminatorName = null;
            for (Type? current = declaredType; current is not null; current = current.BaseType)
            {
                var polymorphic = current.GetCustomAttribute<JsonPolymorphicAttribute>(inherit: false);
                if (polymorphic is null) continue;
                discriminatorName = polymorphic.TypeDiscriminatorPropertyName ?? "$type";
                var supplied = FindJsonProperty(patch, discriminatorName);
                var previous = existing is null ? null : FindJsonProperty(existing, discriminatorName);
                var tag = supplied ?? previous;
                if (tag is null)
                {
                    if (runtimeType is not null || !declaredType.IsAbstract) return true;
                    rejected.Add(JoinPath(prefix, discriminatorName));
                    return false;
                }
                Type? selected = null;
                if (tag.Value.Value is JsonValue value && value.TryGetValue<string>(out var text))
                {
                    foreach (var derived in current.GetCustomAttributes<JsonDerivedTypeAttribute>(inherit: false))
                    {
                        if (derived.TypeDiscriminator is string name && name == text)
                        {
                            selected = derived.DerivedType;
                            break;
                        }
                    }
                }
                if (selected is null || !declaredType.IsAssignableFrom(selected)
                    || (!allowReplacement && runtimeType is not null && runtimeType != selected))
                {
                    rejected.Add(JoinPath(prefix, discriminatorName));
                    return false;
                }
                resolvedType = selected;
                return true;
            }
            return true;
        }

        private static void RetainSharedProperties(JsonObject target, Type previousType, Type replacementType, string discriminatorName)
        {
            var retained = new List<KeyValuePair<string, JsonNode?>>();
            foreach (var entry in target)
            {
                var previous = FindMember(previousType, entry.Key);
                var replacement = FindMember(replacementType, entry.Key);
                if (previous is not null && replacement is not null
                    && previous.Value.Property.PropertyType == replacement.Value.Property.PropertyType)
                {
                    retained.Add(new(replacement.Value.WireName, entry.Value?.DeepClone()));
                }
            }
            var tag = FindJsonProperty(target, discriminatorName)?.Value?.DeepClone();
            target.Clear();
            target[discriminatorName] = tag;
            foreach (var entry in retained) target[entry.Key] = entry.Value;
        }

        private static KeyValuePair<string, JsonNode?>? FindJsonProperty(JsonObject value, string name)
        {
            KeyValuePair<string, JsonNode?>? match = null;
            foreach (var entry in value)
            {
                if (string.Equals(entry.Key, name, StringComparison.OrdinalIgnoreCase)) match = entry;
            }
            return match;
        }

        private static PropertyInfo? DictionaryIndexer(Type type)
        {
            PropertyInfo? readOnlyIndexer = null;
            foreach (var candidate in type.GetInterfaces())
            {
                if (!candidate.IsGenericType) continue;
                var definition = candidate.GetGenericTypeDefinition();
                if (candidate.GetGenericArguments()[0] != typeof(string)) continue;
                if (definition == typeof(IDictionary<,>)) return candidate.GetProperty("Item");
                if (definition == typeof(IReadOnlyDictionary<,>)) readOnlyIndexer = candidate.GetProperty("Item");
            }
            return readOnlyIndexer;
        }

        private static bool TryReadPathValue(object target, string name, out object? value)
        {
            if (DictionaryIndexer(target.GetType()) is { } indexer)
            {
                var contains = indexer.DeclaringType!.GetMethod("ContainsKey")!;
                if (!(bool)contains.Invoke(target, new object[] { name })!)
                {
                    value = null;
                    return false;
                }
                value = indexer.GetValue(target, new object[] { name });
                return true;
            }
            var member = FindMember(target.GetType(), name);
            value = member?.Property.GetValue(target);
            return member is not null;
        }

        private static void RestoreRejectedObjects(object original, object updated, List<string[]> paths)
        {
            foreach (var path in paths)
            {
                object? previous = original;
                object? replacement = updated;
                for (var index = 0; index < path.Length - 1 && previous is not null && replacement is not null; index++)
                {
                    TryReadPathValue(previous, path[index], out previous);
                    TryReadPathValue(replacement, path[index], out replacement);
                }
                if (previous is null || replacement is null || path.Length == 0
                    || !TryReadPathValue(previous, path[^1], out var preserved)) continue;
                if (DictionaryIndexer(replacement.GetType()) is { CanWrite: true } indexer)
                    indexer.SetValue(replacement, preserved, new object[] { path[^1] });
                else
                    FindMember(replacement.GetType(), path[^1])?.Property.SetValue(replacement, preserved);
            }
        }

        /// <summary>
        /// Returns <see langword="true"/> for a model class that a nested object value is merged
        /// into in place: not a string, collection, dictionary, free-form JSON value, or framework type.
        /// </summary>
        private static bool IsModelType(Type type) =>
            type.IsClass
            && type != typeof(string)
            && !typeof(System.Collections.IEnumerable).IsAssignableFrom(type)
            && GetOpenObjectValueType(type) is null
            && type.Namespace is not null
            && type.Namespace != "System"
            && !type.Namespace.StartsWith("System.", StringComparison.Ordinal);

        /// <summary>
        /// Returns <see langword="true"/> when a patch replaces the value of <paramref name="property"/>
        /// instead of merging into it: the property is marked
        /// <c>[JsonObjectCreationHandling(JsonObjectCreationHandling.Replace)]</c>, as
        /// <c>@patchStrategy("replace")</c> emits. Cached because reflection is slow on the PATCH hot path.
        /// </summary>
        private static bool ReplacesOnPatch(PropertyInfo property) =>
            _replacesOnPatch.GetOrAdd(property, static member =>
                member.GetCustomAttribute<JsonObjectCreationHandlingAttribute>()?.Handling == JsonObjectCreationHandling.Replace);

        private static readonly System.Collections.Concurrent.ConcurrentDictionary<PropertyInfo, bool> _replacesOnPatch = new();

        /// <summary>
        /// Applies RFC 7396 merge rules from <paramref name="patch"/> onto <paramref name="target"/>.
        /// Keys of a CLR model must match one of its properties; keys of a dictionary or a
        /// free-form JSON value (<see cref="JsonElement"/>, <see cref="JsonNode"/>, <see cref="object"/>)
        /// are data, so any key is accepted and matched exactly.
        /// </summary>
        private static bool MergeObject(JsonObject target, JsonObject patch, Type targetType, List<string> rejected, string prefix, List<string[]> rejectedObjects, string[] segments)
        {
            if (!TryResolvePatchType(targetType, null, target, patch, rejected, prefix, out var concreteType, out var discriminatorName))
            {
                rejectedObjects.Add(segments);
                return false;
            }
            if (discriminatorName is not null && FindJsonProperty(target, discriminatorName) is not null)
            {
                if (!TryResolvePatchType(targetType, null, target, new JsonObject(), rejected, prefix, out var previousType, out _)) return false;
                if (previousType != concreteType) RetainSharedProperties(target, previousType, concreteType, discriminatorName);
            }
            targetType = concreteType;
            if (discriminatorName is not null && FindJsonProperty(patch, discriminatorName) is { } tag)
            {
                target[discriminatorName] = tag.Value?.DeepClone();
            }
            var openValueType = GetOpenObjectValueType(targetType);
            foreach (var (patchName, patchValue) in patch)
            {
                if (string.Equals(patchName, discriminatorName, StringComparison.OrdinalIgnoreCase)) continue;
                string wireName;
                Type childType;
                var replace = false;
                if (openValueType is not null)
                {
                    wireName = patchName;
                    childType = openValueType;
                }
                else
                {
                    var member = FindMember(targetType, patchName);
                    if (member is null)
                    {
                        rejected.Add(prefix.Length == 0 ? patchName : $"{prefix}.{patchName}");
                        continue;
                    }
                    wireName = member.Value.WireName;
                    childType = member.Value.Property.PropertyType;
                    replace = ReplacesOnPatch(member.Value.Property);
                }
                var path = prefix.Length == 0 ? wireName : $"{prefix}.{wireName}";

                var comparison = openValueType is null ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
                string? targetName = null;
                foreach (var targetEntry in target)
                {
                    if (string.Equals(targetEntry.Key, wireName, comparison))
                    {
                        targetName = targetEntry.Key;
                        break;
                    }
                }
                if (patchValue is null)
                {
                    if (targetName is not null) target.Remove(targetName);
                    continue;
                }

                if (replace)
                {
                    target[targetName ?? wireName] = patchValue.DeepClone();
                    continue;
                }

                if (patchValue is JsonObject patchChild)
                {
                    if (targetName is not null && target[targetName] is JsonObject existingChild)
                    {
                        MergeObject(existingChild, patchChild, childType, rejected, path, rejectedObjects, [.. segments, wireName]);
                    }
                    else
                    {
                        var targetChild = new JsonObject();
                        if (MergeObject(targetChild, patchChild, childType, rejected, path, rejectedObjects, [.. segments, wireName]))
                            target[targetName ?? wireName] = targetChild;
                    }
                    continue;
                }

                target[targetName ?? wireName] = patchValue.DeepClone();
            }
            return true;
        }

        /// <summary>
        /// Returns the value type of an object whose keys are data rather than CLR properties:
        /// <c>TValue</c> for a string-keyed dictionary, <see cref="object"/> for a free-form
        /// JSON value. Returns <see langword="null"/> for a regular model type.
        /// </summary>
        private static Type? GetOpenObjectValueType(Type type)
        {
            type = Nullable.GetUnderlyingType(type) ?? type;
            if (type == typeof(object) || type == typeof(JsonElement) || typeof(JsonNode).IsAssignableFrom(type))
            {
                return typeof(object);
            }
            if (TryGetStringKeyedValueType(type, out var valueType)) return valueType;
            foreach (var candidate in type.GetInterfaces())
            {
                if (TryGetStringKeyedValueType(candidate, out valueType)) return valueType;
            }
            return null;
        }

        private static bool TryGetStringKeyedValueType(Type type, out Type? valueType)
        {
            valueType = null;
            if (!type.IsGenericType) return false;
            var definition = type.GetGenericTypeDefinition();
            if (definition != typeof(IDictionary<,>) && definition != typeof(IReadOnlyDictionary<,>)) return false;
            var arguments = type.GetGenericArguments();
            if (arguments[0] != typeof(string)) return false;
            valueType = arguments[1];
            return true;
        }

        /// <summary>
        /// Asynchronous variant of <see cref="Patch(T, JsonSerializerOptions?)"/>.
        /// Applies all properties defined in this patch to <paramref name="original"/> using
        /// reflection, then returns a completed <see cref="ValueTask"/>.
        /// Throws <see cref="OperationCanceledException"/> if <paramref name="cancellationToken"/>
        /// is already cancelled before work begins.
        /// </summary>
        public ValueTask PatchAsync(T original, JsonSerializerOptions? options = null, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            Patch(original, options);
            return ValueTask.CompletedTask;
        }

        private static PropertyInfo? FindProperty(string name) => FindMember(typeof(T), name)?.Property;

        /// <summary>
        /// Public instance properties of each patched type, except <c>[JsonIgnore]</c> ones, keyed by JSON wire name (case-insensitive),
        /// built once per type because reflection is slow on the PATCH hot path.
        /// </summary>
        private static readonly System.Collections.Concurrent.ConcurrentDictionary<Type, Dictionary<string, (PropertyInfo Property, string WireName)>> _typeProperties = new();

        private static (PropertyInfo Property, string WireName)? FindMember(Type type, string name) =>
            _typeProperties.GetOrAdd(type, BuildPropertyMap).TryGetValue(name, out var member) ? member : null;

        private static Dictionary<string, (PropertyInfo Property, string WireName)> BuildPropertyMap(Type type)
        {
            var map = new Dictionary<string, (PropertyInfo Property, string WireName)>(StringComparer.OrdinalIgnoreCase);
            foreach (var property in type.GetProperties(BindingFlags.Public | BindingFlags.Instance))
            {
                if (property.GetIndexParameters().Length > 0) continue;
                // A [JsonIgnore] property is server-only state: it is not part of the wire
                // contract, so a patch can neither set it nor merge into the object it holds.
                if (property.GetCustomAttribute<JsonIgnoreAttribute>() is { Condition: JsonIgnoreCondition.Always }) continue;
                var wireName = property.GetCustomAttribute<JsonPropertyNameAttribute>()?.Name ?? property.Name;
                map.TryAdd(wireName, (property, wireName));
            }
            return map;
        }

        /// <summary>
        /// The JSON shape of a patch. Reading and writing through it keeps the exact behavior
        /// of <c>[JsonExtensionData]</c>, so the converter only adds <see cref="ReadOptions"/>.
        /// </summary>
        private sealed class Wire
        {
            [JsonExtensionData]
            public Dictionary<string, JsonElement> Properties { get; init; } = new(StringComparer.OrdinalIgnoreCase);

            public IEnumerable<string> DefinedProperties => Properties.Keys;
        }

        /// <summary>
        /// Reads a patch and remembers the serializer options it was read with.
        /// </summary>
        internal sealed class ReadOptionsConverter : JsonConverter<MergePatch<T>>
        {
            public override MergePatch<T>? Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
            {
                // A message-less JsonException gets the same message, path and position as before.
                if (reader.TokenType != JsonTokenType.StartObject) throw new JsonException();
                var wire = JsonSerializer.Deserialize<Wire>(ref reader, options)!;
                return new MergePatch<T> { Properties = wire.Properties, ReadOptions = options };
            }

            public override void Write(Utf8JsonWriter writer, MergePatch<T> value, JsonSerializerOptions options) =>
                JsonSerializer.Serialize(writer, new Wire { Properties = value.Properties }, options);
        }
    }

    /// <summary>
    /// Creates the <see cref="MergePatch{T}"/> converter for each patched type.
    /// </summary>
    [System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverage]
    internal sealed class MergePatchJsonConverterFactory : JsonConverterFactory
    {
        public override bool CanConvert(Type typeToConvert) =>
            typeToConvert.IsGenericType && typeToConvert.GetGenericTypeDefinition() == typeof(MergePatch<>);

        public override JsonConverter? CreateConverter(Type typeToConvert, JsonSerializerOptions options) =>
            (JsonConverter?)Activator.CreateInstance(typeof(MergePatch<>.ReadOptionsConverter).MakeGenericType(typeToConvert.GetGenericArguments()));
    }
}

#pragma warning restore CS0612 // Type or member is obsolete
#pragma warning restore CS1591 // Missing XML comment for publicly visible type or member